import{describe,it,expect}from"vitest";import{AdaptiveRecommender}from"../../frontend/js-modules/adaptive-recommend.js";import{AdaptivePreferenceEngine}from"../../frontend/js-modules/adaptive-preference-engine.js";import{EVENT_TYPES}from"../../frontend/js-modules/interaction-tracker.js";const destinations=[{id:"wild-1",name:"Kaziranga",tags:["wildlife","forests"],budget:"mid",seasons:["winter"]},{id:"beach-1",name:"Goa",tags:["beaches","food"],budget:"mid",seasons:["winter"]},{id:"luxury-1",name:"Udaipur",tags:["heritage"],budget:"luxury",seasons:["winter","summer"]},{id:"wild-2",name:"Ranthambore",tags:["wildlife"],budget:"luxury",seasons:["winter"]}];describe("AdaptiveRecommender — cold start",()=>{it("returns a diverse, clearly-labeled cold-start list when there is no explicit or learned signal",()=>{const e=new AdaptiveRecommender(destinations).recommend({limit:4,random:()=>.5});expect(e).toHaveLength(4),e.forEach(e=>{expect(e.isColdStart).toBe(!0),expect(e.explanation).toMatch(/help us learn your taste/i)})})}),describe("AdaptiveRecommender — learned preferences",()=>{it("ranks wildlife destinations first once the learned profile favors wildlife",()=>{const e=new AdaptivePreferenceEngine({destinations:destinations,now:()=>17e11}).buildProfile([{type:EVENT_TYPES.BOOKMARK,destinationId:"wild-1",timestamp:17e11},{type:EVENT_TYPES.BOOKMARK,destinationId:"wild-2",timestamp:17e11},{type:EVENT_TYPES.RATING,destinationId:"wild-1",rating:5,timestamp:17e11}]),t=new AdaptiveRecommender(destinations).recommend({profile:e,limit:4});expect(t[0].dest.tags).toContain("wildlife"),expect(t[0].isColdStart).toBe(!1),expect(t[0].explanation).toMatch(/wildlife/i)})}),describe("AdaptiveRecommender — explicit preferences",()=>{it("prioritizes destinations matching explicit quiz interests",()=>{const e=new AdaptiveRecommender(destinations).recommend({explicitPrefs:{interests:["beaches"],budget:"any",season:"any"},limit:4});expect(e[0].dest.id).toBe("beach-1"),expect(e[0].explanation).toMatch(/beaches/i)}),it("gives a budget bonus when explicit budget matches the destination tier",()=>{const e=new AdaptiveRecommender(destinations).recommend({explicitPrefs:{interests:[],budget:"luxury",season:"any"},limit:4}).slice(0,2).map(e=>e.dest.budget);expect(e).toContain("luxury")})}),describe("AdaptiveRecommender — exclusions and limits",()=>{it("respects excludeIds and limit",()=>{const e=new AdaptiveRecommender(destinations).recommend({explicitPrefs:{interests:["wildlife"],budget:"any",season:"any"},excludeIds:["wild-1"],limit:10});expect(e.some(e=>"wild-1"===e.dest.id)).toBe(!1)})}),describe("AdaptiveRecommender — performance",()=>{it("stays fast on a large synthetic catalog (acceptance criterion: performant for large datasets)",()=>{const e=Array.from({length:5e3},(e,t)=>({id:`dest-${t}`,name:`Destination ${t}`,tags:[t%2==0?"wildlife":"beaches"],budget:t%3==0?"luxury":"mid",seasons:["winter"]})),t=new AdaptiveRecommender(e),i=Date.now(),n=t.recommend({explicitPrefs:{interests:["wildlife"],budget:"mid",season:"any"},limit:10}),s=Date.now()-i;expect(n).toHaveLength(10),expect(s).toBeLessThan(200)})});